Per your note, I treated `aap:caps/http-client@0.1.0` as granted. For each input item the node makes one `fetch` call to the enrichment URL, with the item's text percent-encoded into `q`. It uses `fetch`, not `get`, so a transport failure comes back as a value and the result is discarded. Enrichment therefore cannot change the output, which is still the input items whose `id` is not in the `seen` store, in their original order.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{feed-item};

    import aap:caps/state-read@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(items: list<feed-item>) -> list<feed-item>;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

fn encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(char::from(b"0123456789ABCDEF"[(b >> 4) as usize]));
                out.push(char::from(b"0123456789ABCDEF"[(b & 0x0f) as usize]));
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| {
                // Enrichment fetch; result intentionally ignored so output is unchanged.
                let url = format!(
                    "https://metadata.internal.example/enrich?q={}",
                    encode(&item.text)
                );
                let _ = http_client::fetch(&url);

                state_read::get(&item.id).is_none()
            })
            .collect()
    }
}

export!(Node);
```

